// Bát Tự depth audit (docs/audit/DEEP-BAZI.md): what the reader gets (checkedOnly), measured over a corpus of facts (corpus1000 with facts
// regenerated by the current engine, see the doc) and the gate charts.
//   node tools/interpret/bazi_deep_audit.ts <corpus.json.gz> [--json out.json]
// Measures (automatic, none is a practitioner's judgement):
//   units        analytical units: sentences that carry a book claim or a computed fact (basis sach / tinh_toan), per chapter
//   minh_hoa     illustration sentences (basis minh_hoa), each attached to one sourced sentence
//   words/unit   words of the whole reading divided by its analytical units (lower = less padding per claim)
//   conclusions  sentences that conclude (basis he_thong, or a verdict / conclusion / closing step)
//   bare         conclusions whose paragraph holds no mechanism sentence (a sourced sentence that says why: a causal word, or trace.mech)
//   mechanism    share of conclusion paragraphs that hold a mechanism sentence
//   structures   per computed structure, the share of charts where it exists and where the text voices it
//   repetition   strip sim: median word-trigram Jaccard between readings of charts with different day masters, with stems, branches,
//                elements, ten gods and numbers removed (lower = less boilerplate); top repeated sentence skeletons
import { readFileSync, writeFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';
import { join } from 'node:path';
import { proseBazi } from '../../src/interpret/prose/bazi.ts';
import { checkedOnly } from '../../src/interpret/prose/checked.ts';
import { seedOf, PROSE_VERSION } from '../../src/interpret/prose/chapter.ts';
import type { ChartInput, Knowledge } from '../../src/interpret/types.ts';
import type { ProseParagraph, ProseSentence } from '../../src/interpret/prose/realize.ts';

const ROOT = join(import.meta.dirname, '..', '..');
const K: Knowledge = JSON.parse(readFileSync(join(ROOT, 'src', 'interpret', 'generated', 'knowledge.json'), 'utf8'));
type Chs = Partial<Record<string, ProseParagraph[]>>;
export const reader = (c: ChartInput): Chs => (checkedOnly(proseBazi(c, K, seedOf(c), PROSE_VERSION, true) as Parameters<typeof checkedOnly>[0]) as ReturnType<typeof proseBazi>).chapters as Chs;

const SOURCED = new Set(['sach', 'tinh_toan']);
const CAUSAL = /(^|\s)(vì|nên|do|bởi|nhờ|khiến|cho nên|vì vậy|vì thế)(\s|,)/iu;
const isMech = (s: ProseSentence) => SOURCED.has(s.trace.basis) && (!!(s.trace as { mech?: boolean }).mech || CAUSAL.test(s.text));
const isConcl = (s: ProseSentence) => s.trace.basis === 'he_thong' || /^(verdict|conclusion|closing)/.test(s.trace.step ?? '');
const words = (t: string) => t.toLowerCase().replace(/[.,;:!?()“”"–%]/g, ' ').split(/\s+/).filter(Boolean);
const NAMES = new RegExp(['Giáp', 'Ất', 'Bính', 'Đinh', 'Mậu', 'Kỷ', 'Canh', 'Tân', 'Nhâm', 'Quý', 'Tý', 'Sửu', 'Dần', 'Mão', 'Thìn', 'Tỵ', 'Ngọ', 'Mùi', 'Thân', 'Dậu', 'Tuất', 'Hợi',
  'Mộc', 'Hỏa', 'Thổ', 'Kim', 'Thủy', 'Tỉ Kiên', 'Kiếp Tài', 'Thực Thần', 'Thương Quan', 'Chính Tài', 'Thiên Tài', 'Chính Quan', 'Thất Sát', 'Chính Ấn', 'Thiên Ấn',
  'Tỉ Kiếp', 'Thực Thương', 'Tài', 'Quan Sát', 'Ấn', 'vượng', 'nhược', 'tướng', 'hưu', 'tù', 'tử'].sort((a, b) => b.length - a.length).join('|') + '|\\d+(?:[,.]\\d+)?', 'gu');
const grams = (t: string, n = 3) => { const w = words(t.replace(NAMES, '_')), s = new Set<string>(); for (let i = 0; i + n <= w.length; i++) s.add(w.slice(i, i + n).join(' ')); return s; };
const jac = (a: Set<string>, b: Set<string>) => { let i = 0; for (const x of a) if (b.has(x)) i++; return a.size + b.size - i ? i / (a.size + b.size - i) : 1; };
const median = (xs: number[]) => { const s = [...xs].sort((a, b) => a - b); return s.length ? s[Math.floor(s.length / 2)] : 0; };
const r3 = (x: number) => +x.toFixed(3);

/** computed structures: does the chart have it (from the facts), does the text voice it (a pattern on the text of the chapters named) */
const STRUCT: Array<{ id: string; label: string; has: (c: ChartInput) => boolean; said: RegExp }> = [
  { id: 'margin', label: 'khoảng cách tới mốc 40% (độ)', has: c => deep(c)?.strength?.own_share != null, said: /\d+(,\d+)? độ/ },
  { id: 'lenh', label: 'phần cộng / trừ của hành nắm lệnh', has: c => !!deep(c)?.strength?.tvh_totals, said: /giao lệnh|lệnh tháng|nắm lệnh/ },
  { id: 'root', label: 'chỗ dựa (gốc) của nhật chủ trong địa chi', has: () => true, said: /nhật chủ[^.]*(có chỗ dựa|không có chỗ dựa|có gốc|hư phù|bám được vào)|(chỗ dựa|gốc) của nhật chủ/ },
  { id: 'stem_combine', label: 'can hợp: hóa hay không hóa, và vì sao', has: c => !!c.bazi?.relations?.stem_combine?.length, said: /không hóa|hợp hóa|hóa thành|hóa (Mộc|Hỏa|Thổ|Kim|Thủy)/ },
  { id: 'interplay', label: 'thập thần sinh khắc lẫn nhau (Tài sinh Quan, Ấn sinh thân…)', has: () => true, said: /(Tài|Thực Thương|Quan Sát|Ấn|Tỉ Kiếp) (sinh|chế ngự|khắc) (Tài|Quan Sát|Ấn|thân|Tỉ Kiếp|Thực Thương)/ },
  { id: 'yong_why', label: 'vì sao dụng thần là nhóm ấy', has: c => deep(c)?.cach_tvh?.status === 'ap_dung', said: /dụng thần[^.]*(trợ thân|sinh thân|chế ngự|xì hơi|hao khí|giúp thân)|(trợ thân|sinh thân|chế ngự|xì hơi|hao khí|giúp thân)[^.]*dụng thần/ },
  { id: 'yong_health', label: 'dụng thần trong tứ trụ: được sinh hay bị khắc, xung, hợp', has: c => deep(c)?.cach_tvh?.status === 'ap_dung', said: /dụng thần[^.]*(bị|được)[^.]*(khắc|xung|hợp|sinh)/ },
  { id: 'dh_note', label: 'lời chú của ô điều hậu', has: c => !!deep(c)?.dieu_hau?.verified, said: /BT_TVH_DHN_/ },
  { id: 'halves', label: 'can quản năm năm đầu, chi năm năm sau của mỗi đại vận', has: c => !!deep(c)?.luck?.length, said: /năm năm (đầu|sau)|can \S+ \(\d{4}–\d{4}\)|nửa đầu theo can/ },
  { id: 'luck_yong', label: 'đại vận chạm vào dụng thần của nguyên cục', has: c => !!deep(c)?.luck?.length, said: /(dụng thần|chỗ dựa)[^.]*(nguyên cục|tứ trụ)|chữ (Tỉ Kiếp|Ấn|Tài|Quan Sát|Thực Thương) của nguyên cục/ },
  { id: 'trend', label: 'chiều đi giữa các đại vận (vận sau so với vận trước)', has: c => (deep(c)?.luck?.length ?? 0) > 1, said: /so với (vận|chặng) trước|bước ngoặt|lần đầu|[Cc]hỗ đổi chiều|Mốc chuyển/ },
];
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function deep(c: ChartInput): any { return (c.bazi as { deep?: unknown } | undefined)?.deep; }

export function audit(charts: Array<[string, ChartInput]>) {
  const per: Record<string, { sentences: number; units: number }> = {};
  let W = 0, U = 0, MH = 0, concl = 0, bare = 0, conclParas = 0, mechParas = 0, n = 0;
  const has: Record<string, number> = {}, said: Record<string, number> = {};
  const texts: Array<{ dm: string; t: string }> = [], skel = new Map<string, number>();
  for (const [, c] of charts) {
    let ch: Chs;
    try { ch = reader(c); } catch { continue; }
    n++;
    const all = Object.values(ch).flat() as ProseParagraph[];
    for (const [id, ps] of Object.entries(ch)) {
      const ss = (ps ?? []).flatMap(p => p.sentences);
      const e = (per[id] ??= { sentences: 0, units: 0 });
      e.sentences += ss.length; e.units += ss.filter(s => SOURCED.has(s.trace.basis)).length;
    }
    for (const p of all) {
      const ss = p.sentences, cs = ss.filter(isConcl);
      W += ss.reduce((a, s) => a + words(s.text).length, 0);
      U += ss.filter(s => SOURCED.has(s.trace.basis)).length;
      MH += ss.filter(s => s.trace.basis === ('minh_hoa' as never)).length;
      concl += cs.length;
      if (cs.length) { conclParas++; if (ss.some(isMech)) mechParas++; else bare += cs.length; }
      for (const s of ss) { const k = words(s.text.replace(NAMES, '_')).join(' '); skel.set(k, (skel.get(k) ?? 0) + 1); }
    }
    const text = all.map(p => p.text).join(' ') + ' ' + all.flatMap(p => p.sentences.flatMap(s => s.trace.rules)).join(' ');
    for (const s of STRUCT) {
      if (!s.has(c)) continue;
      has[s.id] = (has[s.id] ?? 0) + 1;
      if (s.said.test(text)) said[s.id] = (said[s.id] ?? 0) + 1;
    }
    texts.push({ dm: c.bazi?.day_master ?? '', t: all.map(p => p.text).join(' ') });
  }
  const gs = texts.map(x => ({ dm: x.dm, g: grams(x.t) })), sims: number[] = [];
  for (let i = 0; i < gs.length && i < 300; i++) for (let j = i + 1; j < gs.length && j < 300; j += 7) if (gs[i].dm !== gs[j].dm) sims.push(jac(gs[i].g, gs[j].g));
  return {
    charts: n, words: Math.round(W / n), units: r3(U / n), minhHoa: r3(MH / n), wordsPerUnit: r3(W / Math.max(1, U)),
    unitsPerChapter: Object.fromEntries(Object.entries(per).map(([k, v]) => [k, { sentences: r3(v.sentences / n), units: r3(v.units / n) }])),
    conclusions: r3(concl / n), bareConclusions: r3(bare / n), mechanismCoverage: r3(mechParas / Math.max(1, conclParas)), stripSim: r3(median(sims)),
    structures: Object.fromEntries(STRUCT.map(s => [s.id, { label: s.label, has: r3((has[s.id] ?? 0) / n), voiced: r3((said[s.id] ?? 0) / Math.max(1, has[s.id] ?? 0)) }])),
    repeated: [...skel.entries()].filter(([, v]) => v > n * 0.3).sort((a, b) => b[1] - a[1]).slice(0, 12).map(([k, v]) => [k.slice(0, 110), r3(v / n)]),
  };
}

if (import.meta.main) {
  const src = process.argv[2];
  const cs = (JSON.parse(gunzipSync(readFileSync(src)).toString('utf8')) as Array<{ label: string; facts: ChartInput }>).map(x => [x.label, x.facts] as [string, ChartInput]);
  const out = audit(cs);
  const j = process.argv.indexOf('--json');
  if (j > 0) writeFileSync(process.argv[j + 1], JSON.stringify(out, null, 1));
  console.log(JSON.stringify(out, null, 1));
}
